from collections import deque

def comps(mask, neighbors=8):
    H=len(mask); W=len(mask[0]); seen=set(); out=[]
    for r in range(H):
      for c in range(W):
        if mask[r][c] and (r,c) not in seen:
          q=[(r,c)]; seen.add((r,c)); comp=[]
          while q:
            x,y=q.pop(); comp.append((x,y))
            for dx in [-1,0,1]:
              for dy in [-1,0,1]:
                if dx==dy==0 or (neighbors==4 and abs(dx)+abs(dy)!=1): continue
                nx,ny=x+dx,y+dy
                if 0<=nx<H and 0<=ny<W and mask[nx][ny] and (nx,ny) not in seen:
                  seen.add((nx,ny)); q.append((nx,ny))
          out.append(comp)
    return out
